// ------------------------------------------------------------------ teks
export function normalize(s) {
  s = (s || "").toUpperCase().replace(/\s+/g, " ").trim();
  return s.replace(/\s*-\s*/g, "-");
}
export const digits = (s) => (s || "").replace(/\D/g, "");
export function levenshtein(a, b) {
  if (a.length < b.length) [a, b] = [b, a];
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[prev.length - 1];
}
export function cer(ref, hyp) {
  if (!ref) return hyp ? 1 : 0;
  return levenshtein(ref, hyp) / ref.length;
}

// ------------------------------------------------------------------ validator
export const KTP_VOCAB = {
  jenis_kelamin: ["LAKI-LAKI", "PEREMPUAN"],
  gol_darah: ["A", "B", "AB", "O", "-", "A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"],
  agama: ["ISLAM", "KRISTEN", "KATOLIK", "KATHOLIK", "HINDU", "BUDDHA", "BUDHA", "KONGHUCU", "KHONGHUCU",
    "KEPERCAYAAN TERHADAP TUHAN YME"],
  status_perkawinan: ["BELUM KAWIN", "KAWIN", "CERAI HIDUP", "CERAI MATI"],
  kewarganegaraan: ["WNI", "WNA"],
};
const DATE_RE = /^(\d{2})-(\d{2})-(\d{4})$/;
function dateOk(d, m, y) {
  if (m < 1 || m > 12 || d < 1) return false;
  const dim = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return d <= dim && y >= 1;
}
export function parseNik(nik) {
  const s = (nik || "").trim();
  if (!/^\d{16}$/.test(s)) return [null, ["nik_format"]];
  const issues = [];
  const prov = +s.slice(0, 2), kab = +s.slice(2, 4), kec = +s.slice(4, 6);
  const dd = +s.slice(6, 8), mm = +s.slice(8, 10), yy = +s.slice(10, 12), seq = +s.slice(12, 16);
  if (!(prov >= 11 && prov <= 99)) issues.push("nik_provinsi");
  if (kab === 0) issues.push("nik_kabupaten");
  if (kec === 0) issues.push("nik_kecamatan");
  const female = dd > 40;
  const day = female ? dd - 40 : dd;
  if (!(dateOk(day, mm, 1900 + yy) || dateOk(day, mm, 2000 + yy))) issues.push("nik_tanggal");
  if (seq === 0) issues.push("nik_urut");
  return [{ provinsi: prov, kabupaten: kab, kecamatan: kec, hari: day, bulan: mm, yy, perempuan: female }, issues];
}
export function checkKtp(rec) {
  const issues = [];
  let info = null;
  if (rec.nik) {
    const [i, iss] = parseNik(rec.nik);
    info = i;
    issues.push(...iss);
  }
  const tgl = normalize(rec.tanggal_lahir);
  if (tgl) {
    const m = tgl.match(DATE_RE);
    if (!m || !dateOk(+m[1], +m[2], +m[3])) issues.push("tanggal_lahir_format");
    else if (info && (+m[1] !== info.hari || +m[2] !== info.bulan || (+m[3]) % 100 !== info.yy)) issues.push("nik_vs_tanggal_lahir");
  }
  const jk = normalize(rec.jenis_kelamin);
  if (info && KTP_VOCAB.jenis_kelamin.includes(jk) && (jk === "PEREMPUAN") !== info.perempuan) issues.push("nik_vs_jenis_kelamin");
  for (const [field, vocab] of Object.entries(KTP_VOCAB)) {
    const v = normalize(rec[field] || (field === "gol_darah" ? rec.golongan_darah : ""));
    if (v && !vocab.includes(v)) issues.push(`${field}_vocab`);
  }
  const rtrw = normalize(rec.rt_rw);
  if (rtrw && !/^(\d{3}|-)\/(\d{3}|-)$/.test(rtrw)) issues.push("rt_rw_format");
  const berlaku = normalize(rec.berlaku_hingga);
  if (berlaku && berlaku !== "SEUMUR HIDUP") {
    const m = berlaku.match(DATE_RE);
    if (!m || !dateOk(+m[1], +m[2], +m[3])) issues.push("berlaku_hingga_format");
  }
  return issues;
}
export function checkNpwp(rec) {
  const issues = [];
  const raw = (rec.npwp || "").trim();
  const n = digits(raw);
  if (raw) {
    if (n.length !== 15 && n.length !== 16) issues.push("npwp_format");
    else if (n.length === 15 && /\D/.test(raw) && !/^\d{2}\.\d{3}\.\d{3}\.\d-\d{3}\.\d{3}$/.test(raw)) issues.push("npwp_pemisah");
  }
  const nik = (rec.nik || "").trim();
  if (nik) {
    issues.push(...parseNik(nik)[1]);
    if (n.length === 16 && n !== nik) issues.push("npwp_vs_nik");
  }
  return issues;
}
export const CHECKS = { ktp: checkKtp, npwp: checkNpwp };

// ------------------------------------------------------------------ parser
const sortedStr = (a) => [...a].sort();
const KTP_VOCAB_MAIN = {
  jenis_kelamin: ["LAKI-LAKI", "PEREMPUAN"],
  agama: sortedStr(KTP_VOCAB.agama),
  status_perkawinan: sortedStr(KTP_VOCAB.status_perkawinan),
  kewarganegaraan: ["WNI", "WNA"],          // seri -> WNI
};

function longEdge(box) {
  const e1 = [box[1][0] - box[0][0], box[1][1] - box[0][1]];
  const e2 = [box[3][0] - box[0][0], box[3][1] - box[0][1]];
  const e = Math.hypot(...e1) >= Math.hypot(...e2) ? e1 : e2;
  return [Math.atan2(e[1], e[0]), Math.hypot(...e)];
}
export function textAngle(raw) {
  let sx = 0, sy = 0;
  for (const r of raw) {
    const [a, w] = longEdge(r.box);
    sx += w * Math.cos(2 * a);
    sy += w * Math.sin(2 * a);
  }
  return Math.atan2(sy, sx) / 2;
}
function normalizeLines(raw, theta) {
  raw = raw.filter((r) => (r.text || "").trim());
  if (!raw.length) return [];
  const c = Math.cos(-theta), s = Math.sin(-theta);
  const lines = raw.map((r) => {
    const pts = r.box.map(([x, y]) => [x * c - y * s, x * s + y * c]);
    const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
    return { text: r.text, score: r.score ?? 1, x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) };
  });
  const X0 = Math.min(...lines.map((l) => l.x0)), X1 = Math.max(...lines.map((l) => l.x1));
  const Y0 = Math.min(...lines.map((l) => l.y0)), Y1 = Math.max(...lines.map((l) => l.y1));
  const W = Math.max(X1 - X0, 1e-6), H = Math.max(Y1 - Y0, 1e-6);
  for (const l of lines) {
    l.x0 = (l.x0 - X0) / W; l.x1 = (l.x1 - X0) / W;
    l.y0 = (l.y0 - Y0) / H; l.y1 = (l.y1 - Y0) / H;
    l.cy = (l.y0 + l.y1) / 2; l.h = l.y1 - l.y0;
  }
  lines.sort((a, b) => a.cy - b.cy || a.x0 - b.x0);
  return lines;
}
const sameRow = (a, b) => Math.abs(a.cy - b.cy) < 0.6 * Math.max(a.h, b.h);
const compact = (s) => s.toUpperCase().replace(/\s+/g, "");
const isSpace = (ch) => /\s/.test(ch);

export function cleanValue(s) {
  return s.trim().replace(/^[:;.,]+/, "").trim().replace(/\s+/g, " ");
}
export function splitKey(text, keys) {
  const comp = compact(text);
  let best = null;
  for (const key of keys) {
    const tol = key.length <= 4 ? 0 : Math.max(1, Math.floor(key.length / 5));
    for (let n = Math.max(1, key.length - 2); n <= Math.min(comp.length, key.length + 2); n++) {
      const d = levenshtein(comp.slice(0, n), key);
      if (d <= tol && (best === null || d < best.d || (d === best.d && n > best.n))) best = { key, d, n };
    }
  }
  if (!best) return null;
  let i = 0, seen = 0;
  while (i < text.length && seen < best.n) { if (!isSpace(text[i])) seen++; i++; }
  return [best.key, cleanValue(text.slice(i))];
}

const KTP_KEYS = {
  nik: ["NIK"], nama: ["NAMA"], ttl: ["TEMPAT/TGLLAHIR", "TEMPAT/TGL.LAHIR", "TEMPATTGLLAHIR"],
  jenis_kelamin: ["JENISKELAMIN"], gol_darah: ["GOL.DARAH", "GOLDARAH"], alamat: ["ALAMAT"],
  rt_rw: ["RT/RW"], kel_desa: ["KEL/DESA"], kecamatan: ["KECAMATAN"], agama: ["AGAMA"],
  status_perkawinan: ["STATUSPERKAWINAN"], pekerjaan: ["PEKERJAAN"], kewarganegaraan: ["KEWARGANEGARAAN"],
  berlaku_hingga: ["BERLAKUHINGGA"],
};
const KEY_TO_FIELD = {};
for (const [f, ks] of Object.entries(KTP_KEYS)) for (const k of ks) KEY_TO_FIELD[k] = f;
const ALL_KTP_KEYS = Object.keys(KEY_TO_FIELD);

const DIGIT_FIX = { O: "0", D: "0", Q: "0", I: "1", L: "1", "|": "1", Z: "2", S: "5", B: "8", G: "6", T: "7", A: "4" };
export const dedupLead = (d, n) => (d.length === n + 1 && d[0] === d[1] ? d.slice(1) : d);
export function repairNik(d, tanggalLahir = "", jenisKelamin = "") {
  if (d.length !== 17) return d;
  const cands = [];
  for (let i = 0; i < 16; i++) if (d[i] === d[i + 1]) { const c = d.slice(0, i) + d.slice(i + 1); if (!cands.includes(c)) cands.push(c); }
  let best = d, bestScore = -1;
  for (const c of cands) {
    const [info, issues] = parseNik(c);
    if (issues.length) continue;
    let score = 1;
    const m = (tanggalLahir || "").match(/^(\d{2})-(\d{2})-(\d{4})$/);
    if (m && +m[1] === info.hari && +m[2] === info.bulan && (+m[3]) % 100 === info.yy) score += 2;
    if ((jenisKelamin === "LAKI-LAKI" || jenisKelamin === "PEREMPUAN") && (jenisKelamin === "PEREMPUAN") === info.perempuan) score += 1;
    if (score > bestScore) { best = c; bestScore = score; }
  }
  return best;
}
export const fixDigits = (s) => (s || "").toUpperCase().split("").map((c) => DIGIT_FIX[c] ?? c).join("").replace(/\D/g, "");

const PREFIXES = ["KABUPATEN", "KOTA", "KPP PRATAMA", "KPP MADYA", "KANTOR PELAYANAN PAJAK", "KPP"];
export function fixPrefixSpaces(s) {
  const up = s.toUpperCase();
  for (const p of PREFIXES) {
    const comp = p.replace(/ /g, "");
    if (up.replace(/ /g, "").startsWith(comp)) {
      let i = 0, seen = 0;
      while (i < s.length && seen < comp.length) { if (!isSpace(s[i])) seen++; i++; }
      const rest = s.slice(i).trim();
      return rest ? `${p} ${rest}` : p;
    }
  }
  return s;
}
