export function snapVocab(value, vocab, maxCer = 0.34, partial = true) {
  const v = (value || "").toUpperCase().trim();
  if (!v) return value;
  let best = null, bestD = null;
  for (const item of vocab) {
    for (const cand of (partial ? [v, v.slice(0, item.length), v.slice(-item.length)] : [v])) {
      const d = levenshtein(cand, item) / Math.max(item.length, 1);
      if (bestD === null || d < bestD) { best = item; bestD = d; }
    }
  }
  return bestD !== null && bestD <= maxCer ? best : value;
}
const pad2 = (n) => String(n).padStart(2, "0");

function parseKtpLines(lines) {
  const keys = {}, values = {}, used = new Set();
  const push = (f, v) => { (values[f] ||= []).push(v); };
  lines.forEach((l, i) => {
    const m = splitKey(l.text, ALL_KTP_KEYS);
    if (!m) return;
    const field = KEY_TO_FIELD[m[0]];
    if (field in keys || (field !== "gol_darah" && l.x0 > 0.3)) return;
    keys[field] = l;
    used.add(i);
    if (m[1]) push(field, m[1]);
  });
  if (!keys.nik) {   // kata "NIK" salah baca -> baris teratas berisi ~16 digit
    for (let i = 0; i < lines.length; i++) {
      const l = lines[i], nd = fixDigits(l.text).length;
      if (!used.has(i) && nd >= 15 && nd <= 17 && digitRatio(cleanValue(l.text)) >= 0.8) {
        keys.nik = l; used.add(i); push("nik", cleanValue(l.text)); break;
      }
    }
  }
  const nikRow = keys.nik;
  const rows = Object.entries(keys).sort((a, b) => a[1].cy - b[1].cy);
  const assigned = {}, orphans = [];
  lines.forEach((l, i) => {
    if (used.has(i)) return;
    if (nikRow && l.cy < nikRow.y0) return;
    const cands = rows.filter(([f, k]) => sameRow(k, l) && l.x0 >= k.x0 + 0.6 * (k.x1 - k.x0));
    if (!cands.length) { if (l.x0 < 0.65) orphans.push(l); return; }
    const gol = cands.filter((fk) => fk[0] === "gol_darah");
    let field;
    if (gol.length) field = gol[0][0];
    else {
      let best = cands[0];
      for (const fk of cands) if (Math.abs(fk[1].cy - l.cy) < Math.abs(best[1].cy - l.cy)) best = fk;
      field = best[0];
    }
    (assigned[field] ||= []).push(l);
  });
  for (const [field, ls] of Object.entries(assigned)) {
    ls.sort((a, b) => a.x0 - b.x0);
    let prevX1 = keys[field].x1;
    for (let j = 0; j < ls.length; j++) {
      const l = ls[j];
      const gap = l.x0 - prevX1;
      if (j > 0 && (gap > 0.15 || (l.x0 > 0.68 && field !== "nama" && field !== "alamat"))) break;
      if (j === 0 && l.x0 > 0.7 && field !== "gol_darah") break;
      push(field, cleanValue(l.text));
      prevX1 = l.x1;
    }
  }
  for (const fld of ["nama", "alamat"]) {
    if (!keys[fld]) continue;
    const a = keys[fld];
    const below = rows.filter(([f, k]) => k.cy > a.cy + a.h * 0.6).map(([f, k]) => k.cy);
    const limit = below.length ? Math.min(...below) : 1.0;
    for (const l of orphans) if (a.cy < l.cy && l.cy < limit && l.x0 > a.x1 - 0.02 && l.x0 < 0.65) push(fld, cleanValue(l.text));
  }
  const out = {};
  // Titik dua di antara "NIK" dan nilainya kadang terdeteksi sebagai kotak kecil terbaca huruf ("T", "L")
  // yang lalu berubah jadi digit. Buang potongan tanpa angka asli.
  const nikParts = values.nik || [];
  if (nikParts.some((v) => v.replace(/\D/g, "").length >= 10))
    values.nik = nikParts.filter((v) => /\d/.test(v) || v.replace(/\s/g, "").length > 2);
  for (const [f, vs] of Object.entries(values)) out[f] = vs.filter((v) => v).join(" ");

  const ttl = out.ttl || "";
  delete out.ttl;
  if (ttl) {
    const dateRe = /[,.\s]*(\d{1,3})\s*[-.,/ ]+\s*(\d{1,3})\s*[-.,/ ]+\s*(\d{4,5})\s*$/;
    let m = ttl.match(dateRe);
    let place = ttl;
    if (m) place = ttl.slice(0, m.index);
    else if (ttl.includes(",")) {
      const k = ttl.lastIndexOf(",");
      place = ttl.slice(0, k);
      m = ttl.slice(k + 1).toUpperCase().split("").map((c) => DIGIT_FIX[c] ?? c).join("").match(dateRe);
    }
    if (m) {
      const dd = dedupLead(m[1], 2), mm = dedupLead(m[2], 2), yyyy = dedupLead(m[3], 4);
      out.tanggal_lahir = `${pad2(parseInt(dd, 10))}-${pad2(parseInt(mm, 10))}-${yyyy}`;
    }
    const words = cleanValue(place).replace(/[,. ]+$/, "").split(" ");
    while (words.length > 1 && words[words.length - 1].length === 1) words.pop();
    while (words.length > 1 && COLON_LIKE.has(words[0])) words.shift();   // titik dua di depan nilai terbaca "I", "l", "1"
    out.tempat_lahir = words.join(" ");
  }
  if ("nik" in out) out.nik = dedupLead(fixDigits(out.nik), 16);
  if ("rt_rw" in out) {
    out.rt_rw = out.rt_rw.replace(/\s*\/\s*/g, "/");
    const m = out.rt_rw.match(/(\d{3,4}|-)\s*\/\s*(\d{3,4}|-)/);
    if (m) out.rt_rw = `${dedupLead(m[1], 3)}/${dedupLead(m[2], 3)}`;
  }
  if ("berlaku_hingga" in out) {
    const d = out.berlaku_hingga.replace(/\s/g, "");
    const m = d.match(/^(\d{2,3})[-.,]+(\d{2,3})[-.,]+(\d{4,5})$/);
    if (m) out.berlaku_hingga = `${dedupLead(m[1], 2)}-${dedupLead(m[2], 2)}-${dedupLead(m[3], 4)}`;
  }
  if ("gol_darah" in out || "gol_darah" in keys) out.gol_darah = (out.gol_darah || "").replace(/0/g, "O") || "-";
  for (const field of ["jenis_kelamin", "agama", "status_perkawinan", "kewarganegaraan"]) {
    if (field in out) out[field] = snapVocab(out[field].replace(/\s*-\s*/g, "-"), KTP_VOCAB_MAIN[field]);
  }
  if (out.pekerjaan) out.pekerjaan = snapWords(out.pekerjaan, PEKERJAAN, 0.3);
  if (out.berlaku_hingga && !/^\d/.test(out.berlaku_hingga)) out.berlaku_hingga = snapVocab(out.berlaku_hingga, ["SEUMUR HIDUP"]);

  const header = lines.filter((l) => nikRow && l.cy < nikRow.y0);
  for (const l of header) {
    const t = cleanValue(l.text);
    const m = splitKey(t, ["PROVINSI"]);
    if (m && !("provinsi" in out)) out.provinsi = m[1];
    else if (!("kabupaten_kota" in out) && "provinsi" in out) out.kabupaten_kota = fixPrefixSpaces(t);
  }
  if (!("provinsi" in out) && header.length) {   // kata "PROVINSI" salah baca: urutan baris judul
    let words = cleanValue(header[0].text).split(" ");
    if (words.length && levenshtein(words[0].toUpperCase(), "PROVINSI") <= 3) words = words.slice(1);
    out.provinsi = words.join(" ");
    if (header.length > 1 && !("kabupaten_kota" in out)) out.kabupaten_kota = fixPrefixSpaces(cleanValue(header[1].text));
  }
  if ("nik" in out) {
    out.nik = repairNik(out.nik, out.tanggal_lahir || "", out.jenis_kelamin || "");
    fillFromNik(out, lines);
  }
  return out;
}

const THIS_YEAR = new Date().getFullYear();
function fillFromNik(out, lines) {
  const [info, issues] = parseNik(out.nik);
  if (!info || issues.length) return;
  const derived = [];
  if (!out.tanggal_lahir) {
    outer: for (const l of lines) {
      for (const m of l.text.matchAll(/(\d{2})\s*[-.]\s*(\d{2})\s*[-.]\s*(\d{4})/g)) {
        if (+m[1] === info.hari && +m[2] === info.bulan && (+m[3]) % 100 === info.yy) { out.tanggal_lahir = `${m[1]}-${m[2]}-${m[3]}`; break outer; }
      }
    }
    if (!out.tanggal_lahir) {
      const year = 2000 + info.yy > THIS_YEAR - 16 ? 1900 + info.yy : 2000 + info.yy;
      out.tanggal_lahir = `${pad2(info.hari)}-${pad2(info.bulan)}-${year}`;
      derived.push("tanggal_lahir");
    }
  }
  if (!out.jenis_kelamin) { out.jenis_kelamin = info.perempuan ? "PEREMPUAN" : "LAKI-LAKI"; derived.push("jenis_kelamin"); }
  if (derived.length) out._dari_nik = derived;
}

const COLON_LIKE = new Set(["I", "l", "1", "|", "i", "!", ":", ";"]);
export function snapWords(value, vocab, maxCer = 0.3) {
  const words = (value || "").toUpperCase().split(/\s+/).filter((w) => w);
  const vocabWords = new Set(vocab.flatMap((item) => item.split(" ").filter((w) => w.length > 2)));
  for (let k = words.length; k >= 1; k--) {   // awalan terpanjang yang cocok menang
    // Kata yang dibuang harus sampah (kota/tanggal terbit), bukan bagian nama pekerjaan:
    // "PEGAWAI SWASTA" tidak boleh dipangkas jadi "PEGAWAI" lalu dicocokkan ke "PERAWAT".
    if (words.slice(k).some((w) => vocabWords.has(w))) continue;
    const cand = words.slice(0, k).join(" ");
    let best = null, bestD = null;
    for (const item of vocab) {
      const d = levenshtein(cand, item) / Math.max(item.length, 1);
      if (bestD === null || d < bestD) { best = item; bestD = d; }
    }
    if (bestD !== null && bestD <= maxCer) return best;
  }
  return value;
}

// Tanggal terdaftar (sering salah baca: "9/9/A9A", "r18/e2/OO0", "28 Juni 2021"), bukan bagian alamat.
