  const out = new Set(Object.entries(confidence).filter(([f, c]) => c === null || c < threshold).map(([f]) => f));
  for (const i of issues) for (const f of (BY_ISSUE[i] || [i.replace(/_vocab$/, "")])) out.add(f);
