// ------------------------------------------------------------------ dokumen
// Baris OCR -> [jenis dokumen, field]. KTP pada kartu yang diluruskan: kunci hilang ditambah dari template.
// field._dari_nik = field yang diisi dari NIK (perlu dicek).
export function parseDocument(lines, docType = null, warped = false, wilayah = null) {
  const doc = docType || classifyDoc(lines);
  if (warped && doc === "ktp") lines = ktpTemplateKeys(lines);
  let [fields] = bestOrientation(doc, lines);
  if (wilayah && doc === "ktp") {
    const derived = fields._dari_nik;
    delete fields._dari_nik;
    fields = wilayah.snap(fields, fields.nik || "");
    if (derived) fields._dari_nik = derived;
  }
  return [doc, fields];
}
